@php $type=$eventTypeOf($event); $color=$eventColors[$type]??'#64748b'; $localStart=$event->starts_at?->setTimezone($calendarTimezone); @endphp
<a x-show="!categoryHidden('{{ $type }}')" class="cal-ev {{ in_array($event->status,['completed','cancelled'],true)?'done':'' }}" style="border-color:{{ $color }};background:{{ $color }}18;color:{{ $color }}" href="{{ route('collaboration.calendar-events.index',$calendarQuery(['event_id'=>$event->id])) }}" title="{{ $event->title }}"><span class="cal-ev-time">{{ $localStart?->format('g:i A') }}</span><span>{{ $event->title }}</span></a>
